 const offers=document.querySelector('#prepare-offers');if(offers)offers.onclick=async()=>{const ids=[...document.querySelectorAll('[data-offer-candidate]:checked')].map(x=>Number(x.value));if(!ids.length)return note('Choose at least one candidate','error');offers.disabled=true;offers.textContent='Preparing letters…';try{const response=await fetch('/api/offers.zip',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(offerPayload(ids))});if(!response.ok){const e=await response.json();throw new Error(e.detail||'Could not prepare offers')}const blob=await response.blob(),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ICD-offer-letters.zip';a.click();URL.revokeObjectURL(a.href);note('Offer letters prepared')}catch(e){note(e.message,'error')}finally{offers.disabled=false;offers.textContent='Prepare offer letters →'}};
