 const form=document.querySelector('#screen-form');if(form)form.onsubmit=async e=>{e.preventDefault();const fd=new FormData();fd.append('job_id',document.querySelector('#job').value);fd.append('job_role',document.querySelector('#role').value);fd.append('job_details',document.querySelector('#details').value);fd.append('skills_weight',document.querySelector('#skills-weight')?.value||40);fd.append('experience_weight',document.querySelector('#experience-weight')?.value||40);fd.append('education_weight',document.querySelector('#education-weight')?.value||20);[...document.querySelector('#files').files].forEach(f=>fd.append('files',f));document.querySelector('#screen-status').textContent='Screening résumés in parallel…';try{const r=await api('/api/screen',{method:'POST',body:fd});note(`${r.processed} résumés screened`);await refresh('candidates')}catch(err){document.querySelector('#screen-status').textContent=err.message}};
 const jobSelect=document.querySelector('#job');if(jobSelect)jobSelect.onchange=()=>{const j=state.recruiter.jobs.find(x=>String(x.id)===jobSelect.value),preview=document.querySelector('#selected-role-preview');if(!j){if(preview)preview.innerHTML='<i>✎</i><div><b>Manual screening criteria</b><span>Enter a role title and detailed requirements below.</span></div>';return}document.querySelector('#role').value=j.title||'';document.querySelector('#details').value=[j.description,j.responsibilities,(j.required_skills||[]).length?'Required skills: '+j.required_skills.join(', '):''].filter(Boolean).join('\n\n');if(preview)preview.innerHTML=`<i>✓</i><div><b>${esc(j.title)}</b><span>${esc([j.department,j.location,j.employment_type,j.experience_level].filter(Boolean).join(' · '))}</span></div>`};
